local KTool = CS.Engine.Lib.KTool

--- from: Assets/BundleResources/Prefabs/OverseaInvest/OverseaContinuousRechargeDialog.prefab
---@class OverseaContinuousRechargeCell
---@field Env                           	OverseaContinuousRechargeCell           
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field LockNext                      	UnityEngine.RectTransform               
---@field Cur                           	UnityEngine.RectTransform               
---@field Next                          	UnityEngine.RectTransform               
---@field Complete                      	UnityEngine.RectTransform               
---@field Tomorrow                      	UnityEngine.RectTransform               
---@field CanReceive                    	UnityEngine.RectTransform               
---@field Unlock                        	UnityEngine.RectTransform               
---@field Lock                          	UnityEngine.RectTransform               
---@field CommonGoodsList               	Engine.Modules.LuaBehaviour             
---@field TextDay                       	UnityEngine.RectTransform               
---@field ImgFrame2                     	Game.Native.Common.UISwitchImage        
---@field ImgFrame                      	Game.Native.Common.UISwitchImage        
---@field UIFX_Complete                 	UnityEngine.RectTransform               
---@field AnimRoot                      	UnityEngine.Animation                   
local OverseaContinuousRechargeCell = Class('OverseaContinuousRechargeCell')
local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
local CommonGoodsList = "Game.Behaviours.CommonGoodsList"

function OverseaContinuousRechargeCell:__init()
    self.callBack = nil
    self.index = nil
    self.data = nil
end

function OverseaContinuousRechargeCell:__delete()
    self.callBack = nil
    self.index = nil
    self.data = nil
end

function OverseaContinuousRechargeCell:Awake()
    SetButtonAction(self.BtnDrawReward,Bind(self,self.OnDrawRewardRewardClick))
end

function OverseaContinuousRechargeCell:Start()
end

function OverseaContinuousRechargeCell:PlayAnimByEnter(delayIndex)
    CfUtils.PlayDelayShowAnimate(self.AnimRoot, checkInt(delayIndex), 0.05,nil,"OverseaContinuousRechargeDialog_Cell_Entry")
end

function OverseaContinuousRechargeCell:PlayAnimByShowed()
    --printError("PlayerDefault --------------")
    --CfUtils.PlayAnimator(self.AnimRoot, "Default")
end

function OverseaContinuousRechargeCell:SetCallBackAndIndex(callBack,index)
    self.callBack = callBack
    self.index = index
end

function OverseaContinuousRechargeCell:IsHavePay(playerDojo)
    if not isNull(playerDojo.overseaSpecialGift) and isSet(playerDojo.overseaSpecialGift,"signDayNumber") then
        return true
    end
    return false
end

function OverseaContinuousRechargeCell:RefreshShow(data)
    self.data = data
    local playerDojo = playerComponent.playerDojo
    if playerDojo then
        local isHavePay = self:IsHavePay(playerDojo)
        self:SetLockStatus(isHavePay)
        if isHavePay then
            local signDay = playerDojo.overseaSpecialGift.signDayNumber
            local isGet = self:IsGetReward(playerDojo)
            self:SetTagStatus(1)
            self:SetIsGetState(isGet)
            if not isGet then
                ---说明签到天数超过当前天了 直接全显示领取
                if signDay >= self.index then
                    KTool.SetActive(self.CanReceive.gameObject,true)
                    KTool.SetActive(self.Tomorrow.gameObject,false)
                    KTool.SetActive(self.Next.gameObject,false)
                    self:SetTagStatus(2)
                else
                    KTool.SetActive(self.CanReceive.gameObject,false)
                    if signDay + 1 == self.index then
                        KTool.SetActive(self.Tomorrow.gameObject,true)
                        KTool.SetActive(self.Next.gameObject,false)
                    elseif signDay + 1 < self.index then
                        KTool.SetActive(self.Tomorrow.gameObject,false)
                        KTool.SetActive(self.Next.gameObject,true)
                    end
                end
            else
                KTool.SetActive(self.CanReceive.gameObject,false)
                KTool.SetActive(self.Tomorrow.gameObject,false)
                KTool.SetActive(self.Next.gameObject,false)
            end
        else
            KTool.SetActive(self.Cur.gameObject,self.index == 1)
            KTool.SetActive(self.LockNext.gameObject,not (self.index == 1))
        end
        self:SetRewardShow(self.data.rewards)
        self:SetDayShow()
    end
end

function OverseaContinuousRechargeCell:SetIsGetState(isGet)
    KTool.SetActive(self.UIFX_Complete,isGet)
    KTool.SetActive(self.Complete,isGet)
end

function OverseaContinuousRechargeCell:SetTagStatus(status)
    self.ImgFrame.Status = status
    self.ImgFrame2.Status = status
end

function OverseaContinuousRechargeCell:IsGetReward(playerDojo)
    local haveGetDay = playerDojo.overseaSpecialGift.receiveId
    if haveGetDay[tostring(self.index)] then
        return true
    end
    return false
end

function OverseaContinuousRechargeCell:SetDayShow()
    CfUtils.FillText(self.TextDay,0 ..self.index)
end

function OverseaContinuousRechargeCell:SetLockStatus(status)
    KTool.SetActive(self.Lock.gameObject,not status)
    KTool.SetActive(self.Unlock.gameObject,status)
end

function OverseaContinuousRechargeCell:SetRewardShow(rewards)
    if rewards and #rewards > 0 then
        ---@type CommonGoodsList
        local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
        local rewards = checkTable(rewards)
        rewardEnv:FreshBaseUI(rewards)
    end
end

function OverseaContinuousRechargeCell:OnDrawRewardRewardClick()
    local isGet = self:IsGetReward(playerComponent.playerDojo)
    if isGet then return end
    local signDay = playerComponent.playerDojo.overseaSpecialGift.signDayNumber
    if signDay < self.index then return end
    if self.callBack then
        self.callBack(self.index)
    end
end

function OverseaContinuousRechargeCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaContinuousRechargeCell